<include file="Public:header"/><style>	img{		width:100px;		height:50px;	}</style>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('House/open_door_adver')}" class="on">智能硬件广告列表</a>|					<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('House/open_door_adver_add')}','添加广告',800,450,true,false,false,addbtn,'add',true);">添加广告</a>				</ul>			</div>            <table class="search_table" width="100%">                <tr>                    <td>                        <form action="{pigcms{:U('House/open_door_adver')}" method="get">                            <input type="hidden" name="c" value="House"/>                            <input type="hidden" name="a" value="open_door_adver"/>                            智能硬件:&nbsp;&nbsp;                            <select name="intelligent_hardware_type">                                <option value="-1" <if condition="$_GET['intelligent_hardware_type'] eq -1">selected="selected"</if>>全部</option>                                <volist name="intelligent_hardware_type_arr" id="item">                                    <option value="{pigcms{$key}" <if condition="isset($_GET['intelligent_hardware_type']) && $_GET['intelligent_hardware_type'] eq $key">selected="selected"</if>>{pigcms{$item}</option>                                </volist>                            </select>&nbsp;&nbsp;&nbsp;&nbsp;                            广告类型:&nbsp;&nbsp;                            <select name="advert_type">                                <option value="-1" <if condition="$_GET['advert_type'] eq -1">selected="selected"</if>>全部</option>                                <volist name="advert_type_arr" id="items">                                    <option value="{pigcms{$key}" <if condition="isset($_GET['advert_type']) && $_GET['advert_type'] eq $key">selected="selected"</if>>{pigcms{$items}</option>                                </volist>                            </select>                            <input type="submit" value="查询" class="button"/>                        </form>                    </td>                </tr>            </table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup><col> <col> <col><col><col><col><col><col width="180" align="center"> </colgroup>						<thead>							<tr>								<th>编号</th>								<th>智能硬件</th>                                <th>设备类型</th>								<th>广告名称</th>								<th>覆盖{pigcms{$config['house_name']}</th>								<th>广告图片/视频</th>								<th>链接</th>                                <th>点击数</th>                                <th>曝光数</th>                                <th>广告状态</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($adver_list)">								<volist name="adver_list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$intelligent_hardware_type_arr[$vo['intelligent_hardware_type']]}</td>                                        <td>{pigcms{$vo.device_type}</td>										<td>{pigcms{$vo.name}</td>										<td><a href="{pigcms{:U('House/open_door_adv_village',array('adver_id'=>$vo['id']))}"  style="color:blue">指定{pigcms{$config['house_name']}</a></td>                                        <if condition="$vo['advert_type'] neq 1">                                            <td><img src="{pigcms{:replace_file_domain($vo['android_pic'])}" class="view_msg"/></td>                                            <else/>                                            <td>                                                【视频暂不支持在线预览】                                            </td>                                        </if>                                        <if condition="$vo['intelligent_hardware_type'] eq 0 || $vo['intelligent_hardware_type'] eq 3">                                            <td><a target="_blank" href="{pigcms{$vo.url}">链接</a></td>                                            <else/>                                            <td>【暂不支持链接跳转】</td>                                        </if>                                        <if condition="$vo['intelligent_hardware_type'] eq 0">                                            <td style="color: #3283FA;cursor:pointer;" onclick="window.o2oTop.artiframe('{pigcms{:U('House/door_adver_statistics',array('adver_id'=>$vo['id'],'frame_show'=>true))}','点击/曝光详情',600,400,true,false,false,false,'add',true);">                                                {pigcms{$vo.total_click_num}                                            </td>                                            <else/>                                            <td>【无】</td>                                        </if>                                        <td style="color: #3283FA;cursor:pointer;" onclick="window.o2oTop.artiframe('{pigcms{:U('House/door_adver_statistics',array('adver_id'=>$vo['id'],'frame_show'=>true))}','点击/曝光详情',600,400,true,false,false,false,'add',true);">                                            {pigcms{$vo.total_exposure_number}                                        </td>                                        <if condition="$vo.status eq 1">                                            <td>启用</td>                                            <else/>                                            <td>关闭</td>                                        </if>																				<td class="textcenter"><a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('House/open_door_adver_edit',array('id'=>$vo['id'],'frame_show'=>true))}','查看广告详情',800,450,true,false,false,false,'add',true);">查看</a> | <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('House/open_door_adver_edit',array('id'=>$vo['id']))}','编辑广告详情',800,450,true,false,false,editbtn,'add',true);">编辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('House/open_door_adver_del')}">删除</a></td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="10">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="10">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>